-- macOS workaround: mGBA's Scripting "Load script" menu doesn't appear on macOS, so paste the single
-- line below into the Run box at the bottom of the Scripting window and click Run (safe to re-run).
-- Easier alternative: paste  dofile("…/scripts/mgba_bridge.lua")  to load the full readable script.

if not _PPB then _PPB=true; local A={[0]="Forest (Ruby)","Forest (Sapphire)","Plains (Ruby)","Plains (Sapphire)","Ocean (Ruby)","Ocean (Sapphire)","Cave (Ruby)","Cave (Sapphire)","Safari Zone","Volcano","Lake","Wilderness","Ruins (Ruby)","Ruins (Sapphire)"}; local CL,PC,PA={},-1,false; callbacks:add("frame", function() local p=emu:read32(0x020314E0); local act=(p>=0x02000000 and p<0x02040000); if act then local c=emu:read16(p+0x5F0); if not PA then CL={}; PC=c end; if PC>=0 and c>PC then CL[#CL+1]=emu:read16(p+0x59A); PC=c end else CL={}; PC=-1 end; PA=act; _PPN=(_PPN or 0)+1; if _PPN%15~=0 then return end; local ar,c,sp,tg=-1,0,0,-1; if act then ar=emu:read8(p+0x35); c=emu:read16(p+0x5F0); sp=emu:read16(p+0x598); tg=emu:read16(p+0x59A) end; local h={}; for i=0,204 do h[i+1]=string.format("%02x",emu:read8(0x0E000004+i)) end; local j=string.format('{"active":%s,"field":%d,"area":%d,"areaName":"%s","caughtThisGame":%d,"registered":%d,"currentSpecies":%d,"target":%d,"caught":"%s","dex":"%s"}', tostring(act), emu:read8(0x0200B0C4), ar, A[ar] or "-", c, emu:read16(0x02031528), sp, tg, table.concat(CL,","), table.concat(h)); local f=io.open("/tmp/pinball_pokedex_state.json","w"); if f then f:write(j); f:close() end end); console:log("Pinball Pokedex bridge running (live dex + catch tracking)") end
